/**
 * Splits an already encoded query (without the leading '?') into its parameters.
 * The split is done on the encoded string, so that encoded separators
 * (like "%26" or "%3D") are kept as part of the name/value instead of splitting them.
 */
private static List<QueryParameter> splitQueryParameters(String encodedQuery) {
    var parameters = new ArrayList<QueryParameter>();
    if (encodedQuery == null || encodedQuery.isEmpty()) return parameters;
